export function solve(input) {
  const d = input;
  const seen = new Set(),
    out = [];
  const visit = (name) => {
    if (seen.has(name)) return;
    seen.add(name);
    for (const dep of d.packages[name]) visit(dep);
    out.push(name);
  };
  visit(d.root);
  return out;
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const seen = new Set<string>(),
    out: string[] = [];
  const visit = (name: string): void => {
    if (seen.has(name)) return;
    seen.add(name);
    for (const dep of d.packages[name]) visit(dep);
    out.push(name);
  };
  visit(d.root);
  return out;
}
